@keyframes text-glitch-entry {
  0% {
    opacity: 0.7;
    scale: 0.95;
    background-size: 0%;
  }
  20% {
    opacity: 1;
    scale: 1;
    background-size: 0%;
  }
  40% {
    background-size: 60%;
  }
  55% {
    background-size: 110%;
  }
  70% {
    background-size: 90%;
  }
  85% {
    background-size: 105%;
  }
  100% {
    opacity: 1;
    scale: 1;
    background-size: 100%;
  }
