  /* ─── Dia Text: Gradient Sweep ─── */
  function initDiaText() {
    document.querySelectorAll('[data-wp21-block="dia-text"]').forEach(function (el) {
      var raw = el.getAttribute('data-wp21-text');
      var text;
      try { text = JSON.parse(raw); } catch (e) { text = [raw || '']; }
      if (!Array.isArray(text)) text = [text];

      var colorsRaw = el.getAttribute('data-wp21-colors');
      var colors;
      try { colors = JSON.parse(colorsRaw); } catch (e) { colors = ['#c679c4', '#fa3d1d', '#ffb005', '#e1e1fe', '#0358f7']; }

      var duration = parseFloat(el.getAttribute('data-wp21-duration')) || 2;
      var repeat = el.getAttribute('data-wp21-repeat') === 'true';
      var repeatDelay = parseFloat(el.getAttribute('data-wp21-repeat-delay')) || 1.5;

      var contentEl = el.querySelector('.wp21-dia-text-content');
      if (!contentEl) return;

      var currentIndex = 0;
      var textColor = 'transparent';

      function buildGradient(pos) {
        var bandHalf = 17;
        var bandStart = pos - bandHalf;
        var bandEnd = pos + bandHalf;

        if (bandStart >= 100) {
          return 'linear-gradient(90deg, ' + textColor + ', ' + textColor + ')';
        }

        var parts = [];

        if (bandStart > 0) {
          parts.push(textColor + ' 0%');
          parts.push(textColor + ' ' + bandStart.toFixed(2) + '%');
        }

        colors.forEach(function (color, index) {
          var pct = colors.length === 1
            ? pos
            : bandStart + (index / (colors.length - 1)) * bandHalf * 2;
          parts.push(color + ' ' + pct.toFixed(2) + '%');
        });

        if (bandEnd < 100) {
          parts.push('transparent ' + bandEnd.toFixed(2) + '%');
          parts.push('transparent 100%');
        }

        return 'linear-gradient(90deg, ' + parts.join(', ') + ')';
      }

      function animateSweep(callback) {
        var startTime = performance.now();

        contentEl.style.color = 'transparent';
        contentEl.style.webkitBackgroundClip = 'text';
        contentEl.style.backgroundClip = 'text';
        contentEl.style.backgroundSize = '100% 100%';

        function frame(now) {
          var elapsed = (now - startTime) / 1000;
          var t = Math.min(elapsed / duration, 1);
          var eased = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
          var pos = -17 + eased * (117 + 17);
          contentEl.style.backgroundImage = buildGradient(pos);

          if (t < 1) {
            requestAnimationFrame(frame);
          } else {
            contentEl.style.backgroundImage = '';
            contentEl.style.color = '';
            contentEl.style.webkitBackgroundClip = '';
            contentEl.style.backgroundClip = '';
            if (callback) callback();
          }
        }
        requestAnimationFrame(frame);
      }

      function runCycle() {
        animateSweep(function () {
          if (repeat && text.length > 1) {
            setTimeout(function () {
              currentIndex = (currentIndex + 1) % text.length;
              contentEl.textContent = text[currentIndex];
              runCycle();
            }, repeatDelay * 1000);
          }
        });
      }

      contentEl.textContent = text[0];
      runCycle();
    });
  }

  /* ─── Typewriter ─── */
  function initTypewriter() {
    document.querySelectorAll('[data-wp21-block="typewriter"]').forEach(function (el) {
      var raw = el.getAttribute('data-wp21-words');
      var words;
      try { words = JSON.parse(raw); } catch (e) { words = [{ text: 'Hello' }]; }
      if (!Array.isArray(words)) words = [{ text: 'Hello' }];

      var cursorColor = el.getAttribute('data-wp21-cursor-color') || '#3b82f6';
      var textEl = el.querySelector('.wp21-typewriter-text');
      if (!textEl) return;

      textEl.style.borderRightColor = cursorColor;

      var wordIndex = 0;
      var charIndex = 0;
      var isDeleting = false;
      var typeSpeed = 80;
      var deleteSpeed = 40;
      var pauseAfterWord = 1500;

      function type() {
        var currentWord = words[wordIndex].text || '';
        if (!isDeleting) {
          charIndex++;
          textEl.textContent = currentWord.substring(0, charIndex);
          if (charIndex === currentWord.length) {
            isDeleting = true;
            setTimeout(type, pauseAfterWord);
            return;
          }
          setTimeout(type, typeSpeed);
        } else {
          charIndex--;
          textEl.textContent = currentWord.substring(0, charIndex);
          if (charIndex === 0) {
            isDeleting = false;
            wordIndex = (wordIndex + 1) % words.length;
          }
          setTimeout(type, deleteSpeed);
        }
      }

      setTimeout(type, 1000);
    });
