/* ─── Text Glitch ─── */
.wp-block-wp21-text-glitch {
  text-align: center;
  font-size: 2rem;
  font-weight: 700;
}
.wp-block-wp21-text-glitch .wp21-text-glitch {
  display: inline-block;
  position: relative;
  cursor: pointer;
}
.wp-block-wp21-text-glitch .wp21-text-glitch .glitch-text {
  position: relative;
  display: inline-block;
  transition: opacity 0.2s;
}
.wp-block-wp21-text-glitch .wp21-text-glitch .glitch-hover {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0;
  transition: opacity 0.2s;
  background: linear-gradient(90deg, #8b5cf6, #3b82f6, #06b6d4);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  white-space: nowrap;
}
.wp-block-wp21-text-glitch .wp21-text-glitch:hover .glitch-text { opacity: 0; }
.wp-block-wp21-text-glitch .wp21-text-glitch:hover .glitch-hover { opacity: 1; }

/* ─── Text Reveal ─── */
.wp-block-wp21-text-reveal .wp21-text-reveal {
  overflow: hidden;
  font-size: 1.75rem;
  text-align: center;
  max-width: 640px;
  margin: 0 auto;
}
.wp-block-wp21-text-reveal .wp21-text-reveal .reveal-word {
  display: inline-block;
  opacity: 0;
  transform: translateY(100%);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.wp-block-wp21-text-reveal .wp21-text-reveal.is-visible .reveal-word {
  opacity: 1;
  transform: translateY(0);
}

/* ─── Typewriter ─── */
.wp-block-wp21-typewriter {
  text-align: center;
  font-size: 1.5rem;
  font-weight: 700;
  padding: 1.5rem 0;
}
.wp-block-wp21-typewriter .wp21-typewriter-text {
  display: inline;
  white-space: nowrap;
  overflow: hidden;
  border-right: 3px solid #3b82f6;
  animation: typewriter-blink 0.8s step-end infinite;
  padding-right: 4px;
}
@keyframes typewriter-blink {
  50% { border-color: transparent; }
}

/* ─── Dia Text ─── */
.wp-block-wp21-dia-text {
  display: inline;
}
.wp-block-wp21-dia-text .wp21-dia-text-content {
  display: inline;
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
}

/* ─── Text Cycle ─── */
.wp-block-wp21-text-cycle .wp21-cycle-text {
  display: inline-block;
  position: relative;
  font-weight: bold;
  color: #3b82f6;
}

