  padding-right: 4px;
}
@keyframes typewriter-blink {
  50% { border-color: transparent; }
}

/* ─── Dia Text ─── */
.wp-block-wp21-dia-text {
  display: inline;
}
.wp-block-wp21-dia-text .wp21-dia-text-content {
  display: inline;
  background-clip: text;
  -webkit-background-clip: text;
}

/* ─── Text Cycle ─── */
.wp-block-wp21-text-cycle .wp21-cycle-text {
  display: inline-block;
  position: relative;
  font-weight: bold;
  color: inherit;
}

/* ─── Button block dark mode fix ─── */
.dark .wp-block-button__link.has-background {
  background-color: var(--wp--preset--color--fg);
  color: var(--wp--preset--color--bg);
}

