input.newString:
    // Enqueue assets
    add_action('wp_enqueue_scripts', function () {
        wp_enqueue_style(
            'wp21-widgets',
            WP21_EL_URL . 'assets/widgets.css',
            [],
            '1.0.0'
        );

        $asset_file = WP21_EL_PATH . 'assets/frontend.asset.php';
        $deps = [];
        $version = '1.0.2';
        if (file_exists($asset_file)) {
            $asset = include $asset_file;
            $deps = $asset['dependencies'] ?? $deps;
            $version = $asset['version'] ?? $version;
        }

        wp_enqueue_script(
            'wp21-frontend',
            WP21_EL_URL . 'assets/frontend.js',
            $deps,
            $version,
            true
        );

        // Dark mode toggle
        wp_add_inline_script('wp21-frontend', '
document.addEventListener("DOMContentLoaded", function() {
    var btn = document.createElement("button");
    btn.id = "dark-mode-toggle";
    btn.textContent = "🌙";
    btn.style.cssText = "position:fixed;bottom:24px;right:24px;z-index:9999;width:48px;height:48px;border-radius:50%;border:1px solid var(--ic-border,#e3e7ec);background:var(--ic-bg,#fff);color:var(--ic-fg,#111);font-size:20px;cursor:pointer;box-shadow:0 2px 12px rgba(0,0,0,0.1);display:flex;align-items:center;justify-content:center;transition:all 0.3s";
    document.body.appendChild(btn);

    if (window.matchMedia("(prefers-color-scheme: dark)").matches) {
        document.body.classList.add("dark");
        btn.textContent = "☀️";
    }

    btn.addEventListener("click", function() {
        document.body.classList.toggle("dark");
        btn.textContent = document.body.classList.contains("dark") ? "☀️" : "🌙";
    });
});
        ', 'after');
    });

