input.content:
/* ─── Dark Mode Only (matches React #111 / #f6f3ec palette) ─── */
:root {
  --ic-bg: #111111;
  --ic-fg: #f6f3ec;
  --ic-secondary: #9a958a;
  --ic-border: #2b2a25;
  --ic-muted: #171716;
  --ic-hover-bg: #1a1a18;
  --ic-card-bg: #111111;
}
body {
  background-color: var(--ic-bg);
  color: var(--ic-fg);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ─── Gradient Button ─── */
@property --pos-x { syntax: "<percentage>"; initial-value: 11.14%; inherits: false; }
@property --pos-y { syntax: "<percentage>"; initial-value: 140%; inherits: false; }
@property --spread-x { syntax: "<percentage>"; initial-value: 150%; inherits: false; }
@property --spread-y { syntax: "<percentage>"; initial-value: 180.06%; inherits: false; }
@property --color-1 { syntax: "<color>"; initial-value: #000; inherits: false; }
@property --color-2 { syntax: "<color>"; initial-value: #08012c; inherits: false; }
@property --color-3 { syntax: "<color>"; initial-value: #4e1e40; inherits: false; }
@property --color-4 { syntax: "<color>"; initial-value: #70464e; inherits: false; }
@property --color-5 { syntax: "<color>"; initial-value: #88394c; inherits: false; }
@property --border-angle { syntax: "<angle>"; initial-value: 20deg; inherits: true; }
@property --border-color-1 { syntax: "<color>"; initial-value: hsla(340, 75%, 60%, 0.2); inherits: true; }
@property --border-color-2 { syntax: "<color>"; initial-value: hsla(340, 75%, 40%, 0.75); inherits: true; }
@property --stop-1 { syntax: "<percentage>"; initial-value: 37.35%; inherits: false; }
@property --stop-2 { syntax: "<percentage>"; initial-value: 61.36%; inherits: false; }
@property --stop-3 { syntax: "<percentage>"; initial-value: 78.42%; inherits: false; }
@property --stop-4 { syntax: "<percentage>"; initial-value: 89.52%; inherits: false; }
@property --stop-5 { syntax: "<percentage>"; initial-value: 100%; inherits: false; }

.wp21-gradient-btn {
  border-radius: 11px;
  padding: 16px 36px;
  min-width: 132px;
  font-size: 16px;
  line-height: 19px;
  font-weight: 500;
  color: rgba(255 255 255 / 95%);
  text-shadow: 0 0 2px rgba(0, 0, 0, 0.95);
  border: none;
  position: relative;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  text-decoration: none;
  background: radial-gradient(
    var(--spread-x) var(--spread-y) at var(--pos-x) var(--pos-y),
    var(--color-1) var(--stop-1),
    var(--color-2) var(--stop-2),
    var(--color-3) var(--stop-3),
    var(--color-4) var(--stop-4),
    var(--color-5) var(--stop-5)
  );
  outline: none;
  transition:
    --pos-x 0.5s, --pos-y 0.5s,
    --spread-x 0.5s, --spread-y 0.5s,
    --color-1 0.5s, --color-2 0.5s, --color-3 0.5s, --color-4 0.5s, --color-5 0.5s,
    --border-angle 0.5s,
    --border-color-1 0.5s, --border-color-2 0.5s,
    --stop-1 0.5s, --stop-2 0.5s, --stop-3 0.5s, --stop-4 0.5s, --stop-5 0.5s;
}
.wp21-gradient-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background-image: linear-gradient(var(--border-angle), var(--border-color-1), var(--border-color-2));
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: exclude;
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
}
.wp21-gradient-btn:hover {
  --pos-x: 0%;
  --pos-y: 91.51%;
  --spread-x: 120.24%;
  --spread-y: 103.18%;
  --color-1: #c96287;
  --color-2: #c66c64;
  --color-3: #cc7d23;
  --color-4: #37140a;
  --color-5: #000;
  --border-angle: 190deg;
  --border-color-1: hsla(340, 78%, 90%, 0.1);
  --border-color-2: hsla(340, 75%, 90%, 0.6);
  --stop-1: 0%;
  --stop-2: 8.8%;
  --stop-3: 21.44%;
  --stop-4: 71.34%;
  --stop-5: 85.76%;
}
.wp21-gradient-btn.is-variant {
  --color-1: #000022;
  --color-2: #1f3f6d;
  --color-3: #469396;
  --color-4: #f1ffa5;
  --color-5: hsla(250, 80%, 2.5%, 1);
  --pos-x: 40%;
  --pos-y: 140%;
  --spread-x: 130%;
  --spread-y: 170.06%;
  --stop-1: 37.35%;
  --stop-2: 61.36%;
  --stop-3: 78.42%;
  --stop-4: 93.52%;
  --stop-5: 100%;
  --border-angle: 180deg;
  --border-color-1: hsla(320, 75%, 90%, 0.9);
  --border-color-2: hsla(320, 50%, 90%, 0.1);
}
.wp21-gradient-btn.is-variant:hover {
  --pos-x: 0%;
  --pos-y: 120%;
  --spread-x: 110.24%;
  --spread-y: 110.2%;
  --color-1: #000020;
  --color-2: #f1ffa5;
  --color-3: #469396;
  --color-4: #1f3f6d;
  --stop-1: 0%;
  --stop-2: 10%;
  --stop-3: 35.44%;
  --stop-4: 71.34%;
  --stop-5: 150%;
  --border-angle: 190deg;
  --border-color-1: hsla(320, 75%, 90%, 0.1);
  --border-color-2: hsla(320, 50%, 90%, 0.35);
}

/* ─── Dia Text ─── */
.wp-block-wp21-dia-text {
  display: inline;
}
.wp-block-wp21-dia-text .wp21-dia-text-content {
  display: inline;
  background-clip: text;
  -webkit-background-clip: text;
}

/* ─── Typewriter ─── */
.wp-block-wp21-typewriter .wp21-typewriter-text {
  display: inline;
  white-space: nowrap;
  overflow: hidden;
  border-right: 3px solid #3b82f6;
  animation: typewriter-blink 0.8s step-end infinite;
  padding-right: 4px;
}
@keyframes typewriter-blink {
  50% { border-color: transparent; }
}

/* ─── Text Reveal ─── */
.wp-block-wp21-text-reveal .wp21-text-reveal {
  overflow: hidden;
  text-align: center;
  max-width: 640px;
  margin: 0 auto;
}
.wp-block-wp21-text-reveal .wp21-text-reveal .reveal-word {
  display: inline-block;
  opacity: 0;
  transform: translateY(100%);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.wp-block-wp21-text-reveal .wp21-text-reveal.is-visible .reveal-word {
  opacity: 1;
  transform: translateY(0);
}

/* ─── Text Glitch ─── */
.wp-block-wp21-text-glitch .wp21-text-glitch {
  position: relative;
  display: inline-block;
  cursor: pointer;
}
.wp-block-wp21-text-glitch .wp21-text-glitch .glitch-text {
  position: relative;
  display: inline-block;
  transition: opacity 0.1s;
}
.wp-block-wp21-text-glitch .wp21-text-glitch .glitch-hover {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0;
  transition: opacity 0.1s;
  background: linear-gradient(90deg, #8b5cf6, #3b82f6, #06b6d4);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  white-space: nowrap;
}
.wp-block-wp21-text-glitch .wp21-text-glitch::before,
.wp-block-wp21-text-glitch .wp21-text-glitch::after {
  content: attr(data-text);
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.wp-block-wp21-text-glitch .wp21-text-glitch:hover .glitch-text {
  opacity: 0;
  animation: glitch-text-shake 0.4s ease-in-out 2;
}
.wp-block-wp21-text-glitch .wp21-text-glitch:hover .glitch-hover {
  opacity: 1;
  animation: glitch-text-shake 0.4s ease-in-out 2;
}
.wp-block-wp21-text-glitch .wp21-text-glitch:hover::before {
  opacity: 0.7;
  animation: glitch-slice-top 0.4s ease-in-out 2;
  color: #ff0055;
  clip-path: inset(0 0 60% 0);
}
.wp-block-wp21-text-glitch .wp21-text-glitch:hover::after {
  opacity: 0.7;
  animation: glitch-slice-bottom 0.4s ease-in-out 2;
  color: #00ffff;
  clip-path: inset(60% 0 0 0);
}
@keyframes glitch-text-shake {
  0%,100% { transform: translate(0); }
  10% { transform: translate(-1px, 0.5px); }
  20% { transform: translate(1px, -0.5px); }
  30% { transform: translate(-0.5px, 1px); }
  40% { transform: translate(0.5px, -1px); }
  50% { transform: translate(-1px, 0); }
  60% { transform: translate(1px, 0.5px); }
  70% { transform: translate(-0.5px, -0.5px); }
  80% { transform: translate(0.5px, 0); }
  90% { transform: translate(-1px, 0.5px); }
}
@keyframes glitch-slice-top {
  0% { transform: translate(0); clip-path: inset(0 0 60% 0); }
  15% { transform: translate(-3px, -2px); clip-path: inset(0 0 55% 0); }
  30% { transform: translate(2px, 1px); clip-path: inset(0 0 65% 0); }
  45% { transform: translate(-1px, -1px); clip-path: inset(0 0 50% 0); }
  60% { transform: translate(3px, 2px); clip-path: inset(0 0 60% 0); }
  75% { transform: translate(-2px, 0); clip-path: inset(0 0 55% 0); }
  90% { transform: translate(1px, -1px); clip-path: inset(0 0 65% 0); }
  100% { transform: translate(0); clip-path: inset(0 0 60% 0); }
}
@keyframes glitch-slice-bottom {
  0% { transform: translate(0); clip-path: inset(60% 0 0 0); }
  15% { transform: translate(2px, 1px); clip-path: inset(55% 0 0 0); }
  30% { transform: translate(-3px, -2px); clip-path: inset(65% 0 0 0); }
  45% { transform: translate(1px, 2px); clip-path: inset(50% 0 0 0); }
  60% { transform: translate(-2px, -1px); clip-path: inset(60% 0 0 0); }
  75% { transform: translate(3px, 0); clip-path: inset(55% 0 0 0); }
  90% { transform: translate(-1px, 1px); clip-path: inset(65% 0 0 0); }
  100% { transform: translate(0); clip-path: inset(60% 0 0 0); }
}

/* ─── Text Cycle ─── */
.wp-block-wp21-text-cycle .wp21-cycle-text {
  display: inline-block;
  position: relative;
  font-weight: bold;
  color: inherit;
}

/* ─── Bounce animation ─── */
@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

